<script setup>
import {ref,computed} from 'vue'
import {sqlModel,pathModel,htmlModel} from './models.js'
const kind=ref('sql'),input=ref('Books'),safe=ref(false),result=ref(null)
const settings={sql:{title:'A query built from text',presets:['Books',"Books'","Books' OR '1'='1'-- "],label:'Category value'},path:{title:'A file path without a boundary',presets:['cat.png','../notes.txt','%2e%2e%2fnotes.txt'],label:'Requested filename'},html:{title:'Text meets the HTML parser',presets:['hello','<strong>hello</strong>','<img src=x onerror="demo()">'],label:'Search text'}}
const config=computed(()=>settings[kind.value])
function run(){result.value=({sql:sqlModel,path:pathModel,html:htmlModel})[kind.value](input.value,safe.value)}
function change(){input.value=config.value.presets[0];result.value=null}
</script>
<template><section class="sandbox"><div class="sandbox-heading"><div class="eyebrow">TYPE YOUR OWN INPUT · LOCAL MODEL</div><h2>Watch the interpretation change.</h2><p>Three deliberately small models. No real database, shell, filesystem access, network request, or script execution.</p></div><div class="filter-row"><label class="select-label">Model<select v-model="kind" @change="change"><option value="sql">SQL expression</option><option value="path">Path resolution</option><option value="html">HTML parsing</option></select></label><label class="safe-toggle"><input type="checkbox" v-model="safe" @change="run"> Enforce the boundary</label></div><h3>{{config.title}}</h3><div class="preset-list"><button v-for="(p,i) in config.presets" :key="p" class="button" @click="input=p;run()">{{['Normal input','Boundary probe','Variation'][i]}}</button></div><form @submit.prevent="run"><label for="sandbox-input">{{config.label}}</label><textarea id="sandbox-input" v-model="input" maxlength="3000" rows="3" spellcheck="false"></textarea><button class="button primary" type="submit">Run the model →</button></form><div v-if="result" aria-live="polite"><div class="evidence-window"><div class="window-bar">INTERPRETATION</div><pre>{{result.trace}}</pre></div><div class="evidence-window"><div class="window-bar">OBSERVATION</div><pre>{{result.output}}</pre></div><div class="takeaway"><span>WHAT THIS MODEL ESTABLISHES</span><p>{{result.explanation}}</p></div></div><p v-else class="fine-print">Choose a preset or type a value, then run it. Toggle the boundary to compare the same input.</p></section></template>
